INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Dividend$q$, $q$A distribution of part of a company's profit to its shareholders, decided by the board and approved at the AGM.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Dividend Yield$q$, $q$Annual dividend per share divided by the share price, expressed as a percentage.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Payout Ratio$q$, $q$The proportion of net profit paid out as dividends.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Capital Gain$q$, $q$The profit from selling an asset for more than you paid for it.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$ECMA$q$, $q$The Ethiopian Capital Market Authority: the regulator that licenses market participants, approves prospectuses and supervises the capital market.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$ESX$q$, $q$The Ethiopian Securities Exchange: Ethiopia's stock exchange, which began operations with the listing of Wegagen Bank on 10 January 2025.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$NBE$q$, $q$The National Bank of Ethiopia: the central bank. Sets monetary policy, supervises banks, runs T-bill auctions and manages foreign exchange policy.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$CMSP (Capital Market Service Provider)$q$, $q$A firm licensed by ECMA to provide services in the capital market, such as investment banking, securities dealing or investment advice.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Securities Dealer$q$, $q$An ECMA-licensed firm that buys and sells securities on behalf of clients (brokerage) or for its own account.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Investment Bank$q$, $q$A licensed firm that helps companies raise capital by underwriting and arranging share and bond offerings, and that advises on mergers and listings.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
