INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$ESX Neway$q$, $q$The ESX trading app used with licensed securities dealers to place orders for ESX-listed securities.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
