INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Order Book$q$, $q$The list of all outstanding buy (bid) and sell (ask) orders for a security, with their prices and quantities.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
