INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Liquidity$q$, $q$How easily and quickly an asset can be bought or sold without moving its price much.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Volatility$q$, $q$How much and how quickly a price moves up and down. Higher volatility means higher risk.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Market Capitalization (Market Cap)$q$, $q$The total market value of a company's shares: share price multiplied by the total number of shares.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$EPS (Earnings Per Share)$q$, $q$Net profit divided by the number of shares. In Ethiopia it is often reported as a percentage of par value; Stocet shows it in ETB per share.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$P/E (Price-to-Earnings Ratio)$q$, $q$Share price divided by earnings per share: how many years of current earnings you pay for.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$P/B (Price-to-Book Ratio)$q$, $q$Share price divided by book value (equity) per share. Below 1 means the market values the company below its accounting net assets.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Book Value$q$, $q$A company's total assets minus its total liabilities, i.e. shareholders' equity on the balance sheet.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$ROE (Return on Equity)$q$, $q$Net profit divided by shareholders' equity: how much profit is generated for each birr of owners' capital.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$ROA (Return on Assets)$q$, $q$Net profit divided by total assets: how efficiently a company uses all its assets. Above 2% is considered strong for banks.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Net Interest Income (NII)$q$, $q$For a bank: interest earned on loans and investments minus interest paid to depositors and lenders.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Net Interest Margin (NIM)$q$, $q$Net interest income divided by earning assets; the bank's profitability on its lending and investing activities.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Loan-to-Deposit Ratio (LDR)$q$, $q$Total loans divided by total deposits. Shows how much of customers' deposits a bank has lent out.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Non-Performing Loan (NPL)$q$, $q$A loan on which the borrower has stopped paying interest or principal for a defined period, usually 90 days or more.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Impairment (Loan Loss Provision)$q$, $q$An amount set aside in the accounts to cover expected losses on loans and other financial assets.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Capital Adequacy Ratio (CAR)$q$, $q$A bank's regulatory capital divided by its risk-weighted assets; regulators set a minimum to protect depositors.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Cost-to-Income Ratio$q$, $q$Operating costs divided by operating income. A lower number means a more efficient bank.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$EBITDA$q$, $q$Earnings before interest, taxes, depreciation and amortisation: a measure of operating profit commonly used for capital-intensive firms like telecoms.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Par Value$q$, $q$The nominal value printed on a share. ESX-listed Ethiopian banks have a par value of ETB 1,000; Ethio Telecom's is ETB 100.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
