INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$IFRS$q$, $q$International Financial Reporting Standards: the accounting rules ESX-listed companies follow in preparing financial statements.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$AGM (Annual General Meeting)$q$, $q$The yearly meeting at which shareholders approve accounts, elect directors, appoint the auditor and approve dividends.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
