INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Support$q$, $q$A price area where buying has repeatedly stopped a decline.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Resistance$q$, $q$A price area where selling has repeatedly stopped an advance.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Trend$q$, $q$The general direction of price movement: up (higher highs and lows), down (lower highs and lows) or sideways.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Breakout$q$, $q$A move in price beyond a support or resistance level, often on strong buying or selling.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Simple Moving Average (SMA)$q$, $q$The average of the last N closing prices, used to smooth price and reveal the trend.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$EMA (Exponential Moving Average)$q$, $q$A moving average that gives more weight to recent prices so it reacts faster than an SMA.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Moving Average Convergence Divergence (MACD)$q$, $q$A momentum indicator: EMA(12) minus EMA(26), with a 9-period signal line. Crossovers and divergences suggest changes in momentum.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Relative Strength Index (RSI)$q$, $q$A 0 to 100 momentum oscillator. Readings above 70 are considered overbought and below 30 oversold.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Bollinger Bands$q$, $q$A moving average with bands two standard deviations above and below it, showing volatility and price extremes.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$ATR (Average True Range)$q$, $q$A volatility indicator showing the average size of recent price bars; commonly used to set stop-loss distances.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Fibonacci Retracement$q$, $q$Horizontal levels (23.6%, 38.2%, 50%, 61.8%) marking how far a price may pull back before continuing its trend.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Backtest$q$, $q$Applying a trading rule to historical data to see how it would have performed. Results do not guarantee future performance.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Overfitting$q$, $q$Tuning a strategy so tightly to past data that it fits random noise and fails on new data.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Drawdown$q$, $q$The fall from a portfolio's or strategy's peak value to its subsequent low, usually shown as a percentage.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Sharpe Ratio$q$, $q$A measure of return per unit of risk (volatility). Higher is better; computed from the average and standard deviation of returns.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Profit Factor$q$, $q$Gross profit divided by gross loss. Above 1 means a strategy made money; above 1.5 is considered decent.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Stop-Loss$q$, $q$A predetermined price at which you will sell to limit a loss.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Take-Profit$q$, $q$A predetermined price at which you will sell to lock in a gain.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Trailing Stop$q$, $q$A stop-loss that moves up as price rises (never down), protecting profits while letting a winner run.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Reward-to-Risk (R:R)$q$, $q$The potential profit of a trade divided by its potential loss: (target - entry) / (entry - stop).$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Position Sizing$q$, $q$Deciding how many shares to buy so that a stop-out loses no more than a chosen percentage of your account.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Loss Aversion$q$, $q$The tendency to feel losses roughly twice as strongly as equal gains, leading investors to hold losers and sell winners too early.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
INSERT INTO glossary_terms (term, definition, created_at, updated_at) VALUES ($q$Herd Behaviour (FOMO)$q$, $q$Following the crowd, or fear of missing out, often buying after a price has already risen sharply.$q$, now(), now()) ON CONFLICT (term) DO UPDATE SET definition=EXCLUDED.definition, deleted_at=NULL, updated_at=now();
